// ESP32 (Arduino) — L298N 电机调速(LEDC PWM)+ HC-SR04 测距 最小范式
// PWM 必须用 LEDC,不要用 analogWrite。下面是 core 3.x 写法,2.x 见注释。
const int PIN_MOTOR_ENA = 25;   // L298N ENA -> GPIO25(PWM 调速)
const int PIN_MOTOR_IN1 = 26;   // 方向控制
const int PIN_MOTOR_IN2 = 27;
const int PWM_FREQ = 1000;      // PWM 频率 1kHz
const int PWM_BITS = 8;         // 8 位分辨率 -> duty 0~255
const int PIN_TRIG = 5;         // HC-SR04 Trig
const int PIN_ECHO = 18;        // HC-SR04 Echo(5V,经 1k 电阻进 3.3V 脚)

void setup() {
  Serial.begin(115200);
  pinMode(PIN_MOTOR_IN1, OUTPUT);
  pinMode(PIN_MOTOR_IN2, OUTPUT);
  ledcAttach(PIN_MOTOR_ENA, PWM_FREQ, PWM_BITS);   // core 3.x:一行绑定引脚
  // core 2.x 改为: ledcSetup(0, PWM_FREQ, PWM_BITS); ledcAttachPin(PIN_MOTOR_ENA, 0);
  pinMode(PIN_TRIG, OUTPUT);
  pinMode(PIN_ECHO, INPUT);
}

long readDistanceCm() {
  digitalWrite(PIN_TRIG, LOW);  delayMicroseconds(2);
  digitalWrite(PIN_TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(PIN_TRIG, LOW);
  long us = pulseIn(PIN_ECHO, HIGH, 30000);   // 超时 30ms 防卡死
  return us / 58;                              // 微秒换算成厘米
}

void loop() {
  digitalWrite(PIN_MOTOR_IN1, HIGH);
  digitalWrite(PIN_MOTOR_IN2, LOW);
  ledcWrite(PIN_MOTOR_ENA, 180);    // core 3.x:对引脚写占空比(0~255)
  // core 2.x 改为: ledcWrite(0, 180);
  Serial.println(readDistanceCm());
  delay(100);
}
